import json

test_input = [
    [8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 5, 8, 8],
    [8, 5, 5, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8]
]

from collections import Counter
n = Counter(c for row in test_input for c in row)
dot = n.most_common()[-1][0]
H, W = len(test_input), len(test_input[0])
out = [row[:] for row in test_input]
for r in range(H):
    cols = [c for c in range(W) if test_input[r][c] == dot]
    if len(cols) >= 2:
        for c in range(min(cols) + 1, max(cols)):
            if out[r][c] != dot:
                out[r][c] = 3
for c in range(W):
    rws = [r for r in range(H) if test_input[r][c] == dot]
    if len(rws) >= 2:
        for r in range(min(rws) + 1, max(rws)):
            if out[r][c] != dot:
                out[r][c] = 3

print(json.dumps(out))
